// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Sticky".

The distance functions of several randomly positioned crosses are
combined using a smooth minimum function. Additionally, the scene
is rendered twice at different times, with a smooth transition
between the two.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2888149/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
// The smooth edge function (where k determines the amount of blurring)
#define SE(v,a,k) S(a+k/MN,a-k/MN,v)
#define MN min(R.x,R.y)
#define MX max(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// Circular reveal function (works like the aperture of a lens)
#define reveal(p) SE(MN/MX*length(p),sqrt(S(1.,.0,1./T)),1.)
// Smooth min for scalars which can be used as smooth union by making b and k negative
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 a) {
	vec3 p=fract(vec3(a.xyx)*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
// Produces a pattern of randomly positioned crosses which are continuously
// merged together using the smooth minumum function at the top
float scene(vec2 uv, float t) {
	float d=5e5; // initial maximum value for the distance field
	// produces the distance field for three crosses
	for (float i=.0; i<3.; i++) {
		// first calculate the offset (k)
		float
		f=rnd(t-vec2(i+1.,i*10.)),
		k=floor(f*10.)/10.;
		// smoothly add the vertical bar of the cross
		d=smin(d,abs(uv.x+k),.2);
		// then the horizontal
		d=smin(d,abs(uv.y-k),.2);
		// rotate the coordinates by time and a random number
		uv*=rot(T*.2-.39+rnd(uv-uv+k));
	}
	// use a smooth edge function to discretise the distance field and create lines
	return SE(d,.01,5.);
}
// Renders the scenes and does the smooth transition between both of them
vec3 render(vec2 uv) {
	// scale the coordinates (zoom out)
	uv*=4.;
	// calculate two time frames for the scene at different times,
	// and create a smooth transition between them
	float t=T*.5, a=round(t), b=a+1., k=mix(scene(uv,a),scene(uv,b),pow(fract(t+.5),8.));
	// return a black-on-white scene where white is shifted more into yellow and 
	// the transition effect has been exaggerated by projecting k onto a larger range
	return vec3(1,.95,.8)*S(1.4,-.4,k);
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=render(uv);
	// lighten the darkest black to a dark grey
	col=max(col,.08);
	// ensure the color components are confined within the 0-1 range
	col=tanh(col);
	// add the reveal effect at the start of the animation
	col*=reveal(uv);
	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float vig=c.x*c.y*25.;
	vig=pow(vig,.25);
	col*=vig;
	O=vec4(col,1);
}

